// The day's affirmation in Czech, for the country pages in Czech. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Dnes nemusíš zvládnout všechno. Stačí ta další malá věc.\", \"Únava není selhání. Jsi unavená, protože jsi tu pro ně každý den.\", \"Nádobí počká. Máš právo si na pět minut sednout.\", \"Cereálie k večeři se taky počítají jako nakrmená rodina.\", \"Odpočinek si nemusíš zasloužit. Klidně si odpočiň hned teď.\", \"Někdy je vítězství, že to všichni dotáhli až do večerky. To je opravdové vítězství.\", \"Děláš víc, než kdokoli vidí. Já to vidím.\", \"Neuklizený byt a milované děti. To je dobrý obchod.\", \"V těžký den vypadá to tvoje nejlepší jinak, a pořád se počítá.\", \"Jeden hluboký nádech. Spusť ramena. Zvládáš to.\", \"Dnes je v pořádku snížit laťku. Zvednout ji můžeš jindy.\", \"Říct si o pomoc je projev síly, ne slabosti.\", \"Máš právo říct ne další věci navíc.\", \"Jestli ses dnes cítila sama, nejsi jediná máma, která to tak měla. Je nás hodně.\", \"Zasloužíš si kamarádku, která se zeptá, jak se máš, a počká na odpověď.\", \"Klidně se ozvi jako první. Většina mam doufá, že to někdo udělá.\", \"To, že se cítíš neviditelná, neznamená, že na tobě nezáleží. Záleží na tobě moc.\", \"Tvoje pocity dávají smysl. Nejsi „moc“.\", \"Tady nemusíš svůj těžký den vysvětlovat. Rozumíme.\", \"Zpráva jiné mámě se slovy „já taky“ dokáže otočit celý den.\", \"Krmení, přebalování, houpání a znovu dokola. To je skutečná práce, i když to vypadá jako sezení na místě.\", \"Ty a tvoje miminko se pořád ještě poznáváte. Není kam spěchat.\", \"Dny s novorozencem jsou dlouhé. Tohle období nebude trvat věčně.\", \"Jestli jsi dnes jen udržela malého človíčka najedeného a v teple, odvedla jsi velký kus práce.\", \"Nemusíš být rychle zase ve formě. Můžeš prostě být tam, kde jsi.\", \"Ať už miminko krmíš jakkoli, staráš se o něj. To je to, co se počítá.\", \"Můžeš být nevyspalá a plná lásky zároveň.\", \"Pochovej miminko a domácnost nech být. Ta tu bude i potom.\", \"Záchvat vzteku v obchodě z tebe nedělá špatnou mámu. Znamená jen, že máš batole.\", \"Malí zkoušejí hranice, protože se s tebou cítí v bezpečí.\", \"Dnes jsi zůstala klidná o minutu déle než včera. To se počítá.\", \"Jestli ti ujely nervy, obejmutí a „promiň“ spraví hodně. A naučí je to něco dobrého.\", \"Ulepené ručičky, hlasité hlasy, velké emoce. Vychováváš celého člověka.\", \"Páté „proč?“ za hodinu je malá hlavička, která roste.\", \"Ke šťastné vzpomínce nepotřebuješ dokonalý den.\", \"Prásknutí dveřmi není konec příběhu. Nech svítit světlo.\", \"Tvůj puberťák to možná neřekne, ale to, že jsi stále nablízku, je důležité.\", \"Být tou klidnou v domě je dřina. A ty to děláš.\", \"Některé z nejlepších rozhovorů se odehrají v autě. Jen jeď dál.\", \"Vzdalují se, aby dospěli, ne aby tě nechali za sebou.\", \"Nemusíš znát všechny odpovědi. Naslouchání je velká část toho všeho.\", \"Velké děti tě pořád potřebují, jen tišeji.\", \"Zvládat všechno sama chce sílu, kterou většina lidí nikdy neuvidí.\", \"Pro své dítě jsi dost dobrá máma. Vždycky jsi byla.\", \"Jedny ruce, sto úkolů. Buď na sebe hodná.\", \"Tvoje děti se od tebe učí, jak vypadá silný a laskavý člověk.\", \"Pauza neznamená opustit své místo. Díky ní vydržíš.\", \"Nikdo nepočítá body. Záleží na lásce a na tom, že jsi tu.\", \"Smutek a láska pramení ze stejného místa. To, jak moc ti někdo chybí, ukazuje, jak moc jsi milovala.\", \"Na truchlení neexistuje správný harmonogram. Dej si tolik času, kolik potřebuješ.\", \"O těžkých výročích buď k sobě tak jemná, jako bys byla ke kamarádce.\", \"Můžeš v sobě nosit smutek a přesto se smát se svými dětmi. Obojí je skutečné.\", \"Jestli jsi přišla o těhotenství nebo o miminko, ta ztráta je skutečná a tvoje láska také.\", \"Některé dny je smutek tichý a některé hlasitý. Obojí je v pořádku.\", \"Málo peněz neznamená málo lásky.\", \"Tvoje děti si budou pamatovat čas s tebou víc než věci, které jsi koupila.\", \"Zeptat se na pomoc se složenkami je chytré, ne ostudné. Právě kvůli tomu ta pomoc existuje.\", \"Odpoledne v parku zadarmo může být nejlepší den v týdnu.\", \"Vyšla jsi s penězi o týden déle. To chce opravdové umění.\", \"Starosti o peníze vyčerpávají. Neseš toho hodně, a pořád jsi tady.\", \"Dnes jsi vypila sklenici vody. Začni tím.\", \"Všichni vyšli z domu. Boty možná neladily. Stejně je to vítězství.\", \"Zavolala jsi tam, kam se ti tak nechtělo. To bylo statečné.\", \"Dnes ses smála. Drž se toho.\", \"Teplé jídlo, čisté tričko, pohádka na dobrou noc. Z malých věcí se skládá dětství.\", \"Dnes jsi byla k někomu laskavá, i kdyby to byla jen ty sama.\", \"Pokrok, ne dokonalost. Dnes ses posunula dopředu.\", \"Dokončila jsi jednu věc ze seznamu. To je o jednu víc než žádná.\", \"Jsi dobrá máma. To, že si s tím děláš starosti, ukazuje, jak moc ti na tom záleží.\", \"Jsi víc než to, co za den stihneš.\", \"Tvoje děti nepotřebují dokonalou mámu. Potřebují tebe, a tebe mají.\", \"Měj se sebou stejnou trpělivost, jakou máš se svými dětmi.\", \"Máš právo zabírat místo, něco chtít a mít své vlastní sny.\", \"Chyba lásku nesmaže. Zítra je nový začátek.\", \"Pro někoho jsi celý svět, a zároveň jsi taky sama sebou.\", \"Je v pořádku neužívat si každou minutu. Své děti můžeš přesto milovat celým srdcem.\", \"Neexistuje jediný správný způsob, jak být mámou. Tvůj způsob je v pořádku.\", \"Jako v pozici stromu je v pořádku zakolísat. Rovnováhu zase najdeš.\", \"Pevně se postav jako v pozici hory. Stojíš pevněji, než se cítíš.\", \"Válečník II: silné nohy, otevřená náruč. To jsi ty, jak čelíš tomuhle týdnu.\", \"Nádech na čtyři, výdech na čtyři. Jsi tady a zvládáš to.\", \"Roztáhni se doširoka jako hvězda. Máš právo zabírat místo.\", \"Široký, hluboký dřep se těžko drží. Dlouhý den taky. A ty ho držíš.\", \"Můžeš se naklonit jako srpek měsíce a pořád stát.\", \"Na špičky prstů ještě dosáhnout nemusíš. Každý kousek protažení se počítá.\", \"Pozice trojúhelníku: jedna ruka dole, druhá nahoře. Stůj pevně a dál se natahuj.\", \"Je pozdě. Co se dnes nestihlo, počká do zítřka.\", \"V tuhle hodinu vzhůru s miminkem? Spousta mam teď bdí s tebou.\", \"V domě je ticho. Tahle chvíle je tvoje. Dýchej.\", \"Zvládla jsi dnešek. Víc dnešek nepotřeboval.\", \"Jestli ti dnes v noci běží hlava, zapiš si to a nech to počkat do rána.\", \"Zavři oči a odpočiň si. Zítra můžeš začít znovu.\", \"Svátky můžou být těžké, nejen radostné. Ať je pro tebe tohle období jakékoli, je to v pořádku.\", \"Stůl nemusí být dokonalý. Záleží na lidech kolem něj.\", \"Jestli ti letos u stolu někdo chybí, buď ke svému srdci něžná.\", \"Děkuju, mami, za každé jídlo, každé svezení a každé obejmutí.\", \"Nemusíš hostit, péct ani se pořád usmívat. Jednoduché svátky jsou pořád svátky.\", \"Nejlepší dárek, který letos tvoje děti dostanou, je čas s tebou.\", \"Malé svátky jsou taky plné lásky. Aby byly výjimečné, není potřeba moc peněz.\", \"Studené dny, teplá objetí. Ty jsi to teplé místo ve svém domově.\", \"Je v pořádku vynechat část svátečního shonu. Klid je taky dárek.\", \"Jestli je pro tebe letos tohle období těžké, nejsi sama. Den po dni.\"]";D.body.appendChild(e)})();
